CREATE FUNCTION studio_secret_install_partition_guards(parent_key text,leaf_key text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE parent_oid regclass; leaf_oid regclass;
BEGIN
 IF parent_key NOT IN ('studio_secret_use_audit','studio_observed_secret_read_entries','studio_observed_no_send_decisions','studio_observed_terminal_secret_settlements')
  OR leaf_key !~ ('^'||parent_key||'_[0-9]{4}_[0-9]{2}$') THEN
  RAISE EXCEPTION 'secret evidence partition family invalid'; END IF;
 parent_oid:=to_regclass(parent_key);leaf_oid:=to_regclass(leaf_key);
 IF leaf_oid IS NULL OR NOT EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=leaf_oid AND inhparent=parent_oid) THEN
  RAISE EXCEPTION 'secret evidence partition lineage invalid'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=leaf_oid AND tgname='tr_secret_evidence_leaf_truncate') THEN
  EXECUTE format('CREATE TRIGGER tr_secret_evidence_leaf_truncate BEFORE TRUNCATE ON %s FOR EACH STATEMENT EXECUTE FUNCTION studio_secret_audit_immutable()',leaf_oid);
 END IF;
 IF parent_key='studio_observed_no_send_decisions' AND NOT EXISTS(
  SELECT 1 FROM pg_trigger WHERE tgrelid=leaf_oid AND tgname='tr_observed_no_send_commit') THEN
  EXECUTE format('CREATE CONSTRAINT TRIGGER tr_observed_no_send_commit AFTER INSERT ON %s DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION studio_observed_no_send_commit_guard()',leaf_oid);
 END IF;
 IF parent_key='studio_observed_terminal_secret_settlements' AND NOT EXISTS(
  SELECT 1 FROM pg_trigger WHERE tgrelid=leaf_oid AND tgname='tr_observed_terminal_commit') THEN
  EXECUTE format('CREATE CONSTRAINT TRIGGER tr_observed_terminal_commit AFTER INSERT ON %s DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION studio_observed_terminal_commit_guard()',leaf_oid);
 END IF;
END $$;

-- No DEFAULT: an append-only audit must never need PartitionManager's DELETE/move.
-- Backend bootstrap extends this family before traffic, with the existing retention window.
DO $$ DECLARE month_start date; i integer; family text; leaf text; BEGIN
 month_start:=date_trunc('month',clock_timestamp() AT TIME ZONE 'UTC')::date;
 FOREACH family IN ARRAY ARRAY['studio_secret_use_audit','studio_observed_secret_read_entries','studio_observed_no_send_decisions','studio_observed_terminal_secret_settlements'] LOOP
  FOR i IN 0..2 LOOP
   leaf:=family||'_'||to_char(month_start+(i||' months')::interval,'YYYY_MM');
   EXECUTE format('CREATE TABLE %I PARTITION OF %I FOR VALUES FROM (%L) TO (%L)',leaf,family,
    (month_start+(i||' months')::interval)::date,(month_start+((i+1)||' months')::interval)::date);
   PERFORM studio_secret_install_partition_guards(family,leaf);
  END LOOP;
 END LOOP;
END $$;
COMMENT ON TABLE studio_secret_use_audit IS
 'Safe metadata only; UPDATE/DELETE refused. RELEASE/USAGE lifecycle retention uses release_occurred_at monthly detach/drop.';
COMMENT ON COLUMN studio_secret_use_audit.outcome IS
 'Exact six resolution decisions; NULL only for authentic guided no-decision, positively unattempted replay or scoped entered/no-decision terminal usage.';
COMMENT ON COLUMN studio_secret_use_audit.usage_outcome IS
 'Terminal known usage or audit-only UNKNOWN_OUTCOME/genuine guided ACK_LOST; wire remains USED|NOT_USED|REFUSED. Never a value.';

-- Retry authority is names-only and has distinct transport/no-send provenance.
ALTER TABLE studio_dispatch_ledger ADD COLUMN definite_refusal_attempt_id uuid,
 ADD COLUMN zero_send_decision_attempt_id uuid;
CREATE FUNCTION studio_observed_retry_authority_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE e ui_test_executions;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.definite_refusal_attempt_id IS NOT NULL OR NEW.zero_send_decision_attempt_id IS NOT NULL THEN
   RAISE EXCEPTION 'observed retry authority requires a prior decision';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.definite_refusal_attempt_id IS NOT DISTINCT FROM OLD.definite_refusal_attempt_id
  AND NEW.zero_send_decision_attempt_id IS NOT DISTINCT FROM OLD.zero_send_decision_attempt_id THEN RETURN NEW; END IF;
 SELECT * INTO STRICT e FROM ui_test_executions WHERE id=OLD.execution_id AND started_at=OLD.execution_accepted_at;
 IF e.observed_revision_binding IS NULL OR e.observed_admission_receipt IS NOT NULL
  OR OLD.admission_id IS NOT NULL OR NEW.admission_id IS NOT NULL
  OR OLD.cancel_requested_at IS NOT NULL OR OLD.revoked_at IS NOT NULL
  OR OLD.pending_deadline_at IS NOT NULL AND OLD.pending_deadline_at<=clock_timestamp() THEN
  RAISE EXCEPTION 'observed retry authority not pending';
 END IF;
 IF NEW.definite_refusal_attempt_id IS DISTINCT FROM OLD.definite_refusal_attempt_id
  AND NEW.definite_refusal_attempt_id IS NOT NULL THEN
  IF (OLD.state='DISPATCHING' AND OLD.attempt_id=NEW.definite_refusal_attempt_id
   AND OLD.definite_refusal_attempt_id IS NULL
   AND e.observed_revision_binding->>'attemptId'=OLD.attempt_id::text
   AND NEW.state='QUEUED' AND NEW.attempt_id IS NULL AND NEW.lease_owner IS NULL
   AND NEW.lease_expires_at IS NULL
   AND NEW.zero_send_decision_attempt_id IS NOT DISTINCT FROM OLD.zero_send_decision_attempt_id) IS NOT TRUE THEN
   RAISE EXCEPTION 'observed definite refusal transition invalid';
  END IF;
 END IF;
 IF NEW.zero_send_decision_attempt_id IS DISTINCT FROM OLD.zero_send_decision_attempt_id
  AND NEW.zero_send_decision_attempt_id IS NOT NULL THEN
  IF (OLD.state='CLAIMED' AND OLD.attempt_id IS NULL AND OLD.lease_owner IS NOT NULL
   AND OLD.lease_expires_at>clock_timestamp()
   AND e.observed_revision_binding->>'attemptId'=NEW.zero_send_decision_attempt_id::text
   AND NEW.state='QUEUED' AND NEW.attempt_id IS NULL AND NEW.lease_owner IS NULL
   AND NEW.lease_expires_at IS NULL
   AND NEW.definite_refusal_attempt_id IS NOT DISTINCT FROM OLD.definite_refusal_attempt_id
   AND EXISTS(SELECT 1 FROM studio_secret_use_audit a WHERE a.execution_id=OLD.execution_id
    AND a.row_kind='RELEASE' AND a.decision_stage='DISPATCH' AND a.outcome='VAULT_UNAVAILABLE'
    AND a.attempt_id=NEW.zero_send_decision_attempt_id::text)) IS NOT TRUE THEN
   RAISE EXCEPTION 'observed no-send outage transition invalid';
  END IF;
 END IF;
 IF (OLD.definite_refusal_attempt_id IS NOT NULL AND NEW.definite_refusal_attempt_id IS NULL)
  OR (OLD.zero_send_decision_attempt_id IS NOT NULL AND NEW.zero_send_decision_attempt_id IS NULL) THEN
  IF (OLD.state='CLAIMED' AND OLD.attempt_id IS NULL AND OLD.lease_owner IS NOT NULL
   AND OLD.lease_owner=NEW.lease_owner AND OLD.lease_expires_at>clock_timestamp()
   AND NEW.state='DISPATCHING' AND NEW.attempt_id IS NOT NULL
   AND e.observed_revision_binding->>'attemptId'=NEW.attempt_id::text
   AND NEW.attempt_id IS DISTINCT FROM OLD.definite_refusal_attempt_id
   AND NEW.attempt_id IS DISTINCT FROM OLD.zero_send_decision_attempt_id
   AND NEW.definite_refusal_attempt_id IS NULL AND NEW.zero_send_decision_attempt_id IS NULL) IS NOT TRUE THEN
   RAISE EXCEPTION 'observed retry authority consumption invalid';
  END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER tr_observed_retry_authority BEFORE INSERT OR UPDATE ON studio_dispatch_ledger
 FOR EACH ROW EXECUTE FUNCTION studio_observed_retry_authority_guard();

-- Active publication/replay predicates: complete account-free v3 tuple.
CREATE OR REPLACE FUNCTION studio_publication_profile(p jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
 SELECT p='{"catalog":"observed-replay-3","playwright":"1.63.0","browserEngine":"chromium","contract":3,"learnedPlan":3,"observation":3,"guidedPolicy":3,"referencePolicy":4,"lowering":2,"artifact":3,"language":"observed-3","executor":"observed-4","publicationEvidence":1,"validationBasis":1,"validator":"observed-2","protocol":3,"replayAuthorization":2}'::jsonb
$$;

package com.citi.put.checks.studio.secrets;

import com.citi.put.checks.studio.guided.session.GuidedContracts;
import com.fasterxml.jackson.databind.JsonNode;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.UUID;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Append-only safe metadata, in the caller's dispatch/outcome transaction. Never accepts a value.
 */
@Component
public class SecretUseAuditRecorder {
  public enum Path {
    GUIDED,
    OBSERVED_REPLAY
  }

  public enum NoSendDisposition {
    CLOSED,
    REQUEUED
  }

  public enum ResolutionOutcome {
    RESOLVED,
    NOT_AUTHORIZED,
    REVOKED,
    UNAVAILABLE,
    VAULT_UNAVAILABLE,
    REVOKED_MID_RUN
  }

  public enum UsageOutcome {
    USED,
    NOT_USED,
    REFUSED,
    OK,
    ASSERTION_FAILED,
    TARGET_CHANGED,
    POLICY_DENIED,
    TIMEOUT,
    ACK_LOST,
    UNKNOWN_OUTCOME,
    CANCELLED
  }

  public record Scope(
      Path path,
      UUID executionId,
      String sessionId,
      String admissionId,
      String principalId,
      String csiId,
      String environment,
      UUID testId,
      String secretId,
      String attemptId,
      Long releaseSeq,
      String coordinateStepId,
      Integer coordinateOrdinal,
      String sourceReferenceId) {
    public Scope {
      Objects.requireNonNull(path);
      Objects.requireNonNull(testId);
      bounded(principalId, 256);
      bounded(csiId, 20);
      bounded(environment, 256);
      bounded(attemptId, 256);
      if (secretId == null
          || !secretId.matches("[A-Za-z0-9_.-]{1,64}")
          || releaseSeq != null && releaseSeq < 1
          || coordinateStepId == null && coordinateOrdinal != null
          || coordinateOrdinal != null && coordinateOrdinal < 0) throw invalid();
      if (coordinateStepId != null) bounded(coordinateStepId, 256);
      if (admissionId != null) bounded(admissionId, 256);
      if (sourceReferenceId != null) bounded(sourceReferenceId, 256);
      if (path == Path.GUIDED) {
        bounded(sessionId, 256);
        if (executionId != null || coordinateStepId == null) throw invalid();
      } else if (executionId == null
          || sessionId != null
          || admissionId != null
          || coordinateStepId != null
          || coordinateOrdinal != null
          || sourceReferenceId != null) throw invalid();
    }

    public Scope(
        Path path,
        UUID executionId,
        String sessionId,
        String admissionId,
        String principalId,
        String csiId,
        String environment,
        UUID testId,
        String secretId,
        String attemptId,
        long releaseSeq,
        String coordinateStepId,
        Integer coordinateOrdinal) {
      this(
          path,
          executionId,
          sessionId,
          admissionId,
          principalId,
          csiId,
          environment,
          testId,
          secretId,
          attemptId,
          Long.valueOf(releaseSeq),
          coordinateStepId,
          coordinateOrdinal,
          null);
    }
  }

  public record Release(
      UUID id, Instant releasedAt, Scope scope, String vaultVersion, ResolutionOutcome outcome) {
    public Release {
      Objects.requireNonNull(id);
      Objects.requireNonNull(releasedAt);
      Objects.requireNonNull(scope);
      Objects.requireNonNull(outcome);
      if (scope.releaseSeq() == null
          || scope.path() == Path.GUIDED
              && (scope.admissionId() == null || scope.coordinateOrdinal() == null))
        throw invalid();
      if (vaultVersion != null) bounded(vaultVersion, 256);
      if (outcome == ResolutionOutcome.RESOLVED && vaultVersion == null) throw invalid();
    }
  }

  private static final List<String> COLUMNS =
      List.of(
          "id",
          "occurred_at",
          "release_occurred_at",
          "path",
          "row_kind",
          "release_id",
          "affected_release_id",
          "decision_stage",
          "attempt_id",
          "release_seq",
          "execution_id",
          "session_id",
          "admission_id",
          "principal_id",
          "csi_id",
          "environment",
          "test_id",
          "secret_id",
          "vault_version",
          "coordinate_step_id",
          "coordinate_ordinal",
          "source_reference_id",
          "outcome",
          "usage_outcome");
  private final JdbcTemplate jdbc;
  private final NamedParameterJdbcTemplate named;
  private final Clock clock;

  @Autowired
  public SecretUseAuditRecorder(JdbcTemplate jdbc) {
    this(jdbc, Clock.systemUTC());
  }

  public SecretUseAuditRecorder(JdbcTemplate jdbc, Clock clock) {
    this.jdbc = Objects.requireNonNull(jdbc);
    this.named = new NamedParameterJdbcTemplate(jdbc);
    this.clock = Objects.requireNonNull(clock);
  }

  @Transactional(propagation = Propagation.MANDATORY)
  public Release recordRelease(Scope scope, String vaultVersion, ResolutionOutcome outcome) {
    Objects.requireNonNull(outcome);
    if (outcome == ResolutionOutcome.REVOKED_MID_RUN
        || scope.releaseSeq() == null
        || scope.path() == Path.GUIDED
            && (scope.admissionId() == null || scope.coordinateOrdinal() == null)) throw invalid();
    if (vaultVersion != null) bounded(vaultVersion, 256);
    if (outcome == ResolutionOutcome.RESOLVED && vaultVersion == null) throw invalid();
    UUID id = identity("release", scope, null);
    Instant now = now();
    Map<String, Object> row =
        row(scope, id, now, now, "RELEASE", id, null, "DISPATCH", vaultVersion, outcome, null);
    Map<String, Object> stored = append(scope, row);
    return new Release(
        id,
        ((Timestamp) stored.get("release_occurred_at")).toInstant(),
        scope,
        vaultVersion,
        outcome);
  }

  @Transactional(propagation = Propagation.MANDATORY)
  public void recordUsage(Release release, UsageOutcome usage) {
    Objects.requireNonNull(release);
    Objects.requireNonNull(usage);
    if (release.scope().path() == Path.OBSERVED_REPLAY
        && usage != UsageOutcome.USED
        && usage != UsageOutcome.NOT_USED
        && usage != UsageOutcome.REFUSED
        && usage != UsageOutcome.UNKNOWN_OUTCOME) throw invalid();
    append(
        release.scope(),
        row(
            release.scope(),
            identity("usage", release.scope(), release.id()),
            now(),
            release.releasedAt(),
            "USAGE",
            release.id(),
            null,
            null,
            release.vaultVersion(),
            release.outcome(),
            usage));
  }

  @Transactional(propagation = Propagation.MANDATORY)
  public void recordUnreachedGuided(Scope scope) {
    if (scope.path() != Path.GUIDED
        || scope.admissionId() != null
        || scope.coordinateOrdinal() != null
        || scope.releaseSeq() != null
        || scope.sourceReferenceId() == null) throw invalid();
    requireTransaction();
    String state =
        jdbc.queryForObject(
            "SELECT state FROM studio_guided_sessions WHERE session_id=? FOR UPDATE",
            String.class,
            scope.sessionId());
    if (!List.of(
            "FINALIZING",
            "SUCCEEDED",
            "PUBLICATION_CONFLICT",
            "FAILED",
            "UNKNOWN_OUTCOME",
            "CANCELLED",
            "EXPIRED")
        .contains(state)) throw invalid();
    Instant now = now();
    append(
        scope,
        row(
            scope,
            identity("unreached", scope, null),
            now,
            now,
            "USAGE",
            null,
            null,
            null,
            null,
            null,
            UsageOutcome.NOT_USED));
  }

  /** Consume committed, but no resolution decision committed; never a no-read/no-use claim. */
  @Transactional(propagation = Propagation.MANDATORY)
  public void recordConsumedNoDecision(Scope scope, UsageOutcome usage) {
    if (scope.path() != Path.GUIDED
        || scope.admissionId() == null
        || scope.coordinateOrdinal() == null
        || scope.releaseSeq() != null
        || usage != UsageOutcome.UNKNOWN_OUTCOME && usage != UsageOutcome.ACK_LOST) throw invalid();
    requireTransaction();
    String state =
        jdbc.queryForObject(
            "SELECT state FROM studio_guided_sessions WHERE session_id=? FOR UPDATE",
            String.class,
            scope.sessionId());
    if (!List.of(
            "FINALIZING",
            "SUCCEEDED",
            "PUBLICATION_CONFLICT",
            "FAILED",
            "UNKNOWN_OUTCOME",
            "CANCELLED",
            "EXPIRED")
        .contains(state)) throw invalid();
    Instant now = now();
    append(
        scope,
        row(
            scope,
            identity("consumed-uncertain", scope, null),
            now,
            now,
            "USAGE",
            null,
            null,
            null,
            null,
            null,
            usage));
  }

  @Transactional(propagation = Propagation.MANDATORY)
  public void recordLiveRevocation(Release release) {
    Objects.requireNonNull(release);
    if (release.outcome() != ResolutionOutcome.RESOLVED) throw invalid();
    UUID id = identity("revocation", release.scope(), release.id());
    append(
        release.scope(),
        row(
            release.scope(),
            id,
            now(),
            release.releasedAt(),
            "RELEASE",
            id,
            release.id(),
            "LIVE_RECHECK",
            release.vaultVersion(),
            ResolutionOutcome.REVOKED_MID_RUN,
            null));
  }

  /** Durable possible-read entry, committed by the caller before the existing provider call. */
  @Transactional(propagation = Propagation.MANDATORY)
  public void recordObservedReadEntry(JsonNode binding, String leaseOwner, String secretId) {
    if (secretId == null || !secretId.matches("[A-Za-z0-9_.-]{1,64}")) throw invalid();
    Map<String, Object> metadata = observedMetadata(binding, leaseOwner);
    metadata.put(
        "id",
        UUID.nameUUIDFromBytes(
            ("read|"
                    + metadata.get("execution_id")
                    + "|"
                    + metadata.get("attempt_id")
                    + "|"
                    + secretId)
                .getBytes(StandardCharsets.UTF_8)));
    metadata.put("secret_id", secretId);
    metadata.put("occurred_at", Timestamp.from(now()));
    var existing =
        jdbc.queryForList(
            "SELECT * FROM studio_observed_secret_read_entries WHERE execution_id=? AND attempt_id=? AND secret_id=?",
            metadata.get("execution_id"),
            metadata.get("attempt_id"),
            secretId);
    if (!existing.isEmpty()) {
      var stored = existing.getFirst();
      for (var field : metadata.entrySet()) {
        // One conservative entered fact survives another real pass/owner; creator metadata stays
        // immutable.
        if (field.getKey().equals("occurred_at") || field.getKey().equals("lease_owner")) continue;
        if (!Objects.equals(stored.get(field.getKey()), field.getValue()))
          throw new IllegalStateException("Conflicting observed read-entry scope");
      }
      return;
    }
    named.update(
        "INSERT INTO studio_observed_secret_read_entries(id,occurred_at,execution_id,execution_accepted_at,attempt_id,revision_id,revision_digest,binding_digest,scope_hash,principal_id,csi_id,environment,test_id,lease_owner,secret_id) VALUES (:id,:occurred_at,:execution_id,:execution_accepted_at,:attempt_id,:revision_id,:revision_digest,:binding_digest,:scope_hash,:principal_id,:csi_id,:environment,:test_id,:lease_owner,:secret_id)",
        metadata);
  }

  /** Safe positive absence and owner transition must commit together; this grants no retry. */
  @Transactional(propagation = Propagation.MANDATORY)
  public void recordObservedNoSend(
      JsonNode binding,
      String leaseOwner,
      Set<String> positivelyNotEnteredIds,
      NoSendDisposition disposition) {
    Objects.requireNonNull(disposition);
    Objects.requireNonNull(positivelyNotEnteredIds);
    if (positivelyNotEnteredIds.size() > 64
        || positivelyNotEnteredIds.stream()
            .anyMatch(id -> id == null || !id.matches("[A-Za-z0-9_.-]{1,64}"))) throw invalid();
    Map<String, Object> metadata = observedMetadata(binding, leaseOwner);
    metadata.put(
        "id",
        UUID.nameUUIDFromBytes(
            ("no-send|" + metadata.get("execution_id") + "|" + metadata.get("attempt_id"))
                .getBytes(StandardCharsets.UTF_8)));
    metadata.put("occurred_at", Timestamp.from(now()));
    metadata.put("disposition", disposition.name());
    var names = new GuidedContracts().object().putArray("ids");
    positivelyNotEnteredIds.stream().sorted().forEach(names::add);
    metadata.put("not_entered_ids", names.toString());
    named.update(
        "INSERT INTO studio_observed_no_send_decisions(id,occurred_at,execution_id,execution_accepted_at,attempt_id,revision_id,revision_digest,binding_digest,scope_hash,principal_id,csi_id,environment,test_id,lease_owner,not_entered_ids,disposition) VALUES (:id,:occurred_at,:execution_id,:execution_accepted_at,:attempt_id,:revision_id,:revision_digest,:binding_digest,:scope_hash,:principal_id,:csi_id,:environment,:test_id,:lease_owner,CAST(:not_entered_ids AS jsonb),:disposition)",
        metadata);
    for (String secret : positivelyNotEnteredIds) {
      Scope scope =
          new Scope(
              Path.OBSERVED_REPLAY,
              (UUID) metadata.get("execution_id"),
              null,
              null,
              (String) metadata.get("principal_id"),
              (String) metadata.get("csi_id"),
              (String) metadata.get("environment"),
              (UUID) metadata.get("test_id"),
              secret,
              metadata.get("attempt_id").toString(),
              null,
              null,
              null,
              null);
      Instant at = ((Timestamp) metadata.get("occurred_at")).toInstant();
      append(
          scope,
          row(
              scope,
              identity("unattempted", scope, null),
              at,
              at,
              "USAGE",
              null,
              null,
              null,
              null,
              null,
              UsageOutcome.NOT_USED));
    }
  }

  /** Actual pre-send terminal winner, with independently verified planned close metadata. */
  @Transactional(propagation = Propagation.MANDATORY)
  public boolean recordObservedTerminalSettlement(
      UUID executionId, String plannedErrorCode, Instant plannedEndedAt) {
    requireTransaction();
    Objects.requireNonNull(executionId);
    Objects.requireNonNull(plannedEndedAt);
    if (plannedErrorCode == null || !plannedErrorCode.matches("[A-Z][A-Z0-9_]{0,63}"))
      throw invalid();
    var rows =
        jdbc.queryForList(
            "SELECT l.execution_id,l.execution_accepted_at,CAST(e.observed_revision_binding->>'attemptId' AS uuid) AS attempt_id,e.revision_id,e.observed_revision_binding->>'revisionDigest' AS revision_digest,studio_publication_hash(e.observed_revision_binding) AS binding_digest,e.observed_revision_binding->>'scopeHash' AS scope_hash,l.principal AS principal_id,l.csi_id,e.environment,l.test_id,e.ended_at AS retained_ended_at FROM studio_dispatch_ledger l JOIN ui_test_executions e ON e.id=l.execution_id AND e.started_at=l.execution_accepted_at WHERE l.execution_id=? AND l.state IN ('QUEUED','CLAIMED') AND l.attempt_id IS NULL AND l.admission_id IS NULL AND e.status='PENDING' AND e.observed_admission_receipt IS NULL AND e.observed_revision_binding IS NOT NULL FOR UPDATE OF l,e",
            executionId);
    if (rows.isEmpty()) return false;
    var metadata = new LinkedHashMap<>(rows.getFirst());
    var expected =
        new GuidedContracts()
            .parse(
                jdbc.queryForObject(
                    "SELECT studio_observed_terminal_classification(?,?)::text",
                    String.class,
                    executionId,
                    metadata.get("attempt_id")));
    if (expected.path("noReadIds").isEmpty() && expected.path("possibleReadIds").isEmpty())
      return false;
    metadata.put(
        "id",
        UUID.nameUUIDFromBytes(
            ("terminal|" + executionId + "|" + metadata.get("attempt_id"))
                .getBytes(StandardCharsets.UTF_8)));
    metadata.put("occurred_at", Timestamp.from(now()));
    metadata.put("terminal_error_code", plannedErrorCode);
    var oldEnded = (Timestamp) metadata.remove("retained_ended_at");
    metadata.put("terminal_ended_at", oldEnded != null ? oldEnded : Timestamp.from(plannedEndedAt));
    metadata.put("no_read_ids", expected.path("noReadIds").toString());
    metadata.put("possible_read_ids", expected.path("possibleReadIds").toString());
    named.update(
        "INSERT INTO studio_observed_terminal_secret_settlements(id,occurred_at,execution_id,execution_accepted_at,attempt_id,revision_id,revision_digest,binding_digest,scope_hash,principal_id,csi_id,environment,test_id,terminal_error_code,terminal_ended_at,no_read_ids,possible_read_ids) VALUES (:id,:occurred_at,:execution_id,:execution_accepted_at,:attempt_id,:revision_id,:revision_digest,:binding_digest,:scope_hash,:principal_id,:csi_id,:environment,:test_id,:terminal_error_code,:terminal_ended_at,CAST(:no_read_ids AS jsonb),CAST(:possible_read_ids AS jsonb))",
        metadata);
    for (String field : List.of("noReadIds", "possibleReadIds"))
      for (JsonNode id : expected.path(field)) {
        String secret = id.asText();
        UsageOutcome usage =
            field.equals("noReadIds") ? UsageOutcome.NOT_USED : UsageOutcome.UNKNOWN_OUTCOME;
        Scope scope =
            new Scope(
                Path.OBSERVED_REPLAY,
                executionId,
                null,
                null,
                (String) metadata.get("principal_id"),
                (String) metadata.get("csi_id"),
                (String) metadata.get("environment"),
                (UUID) metadata.get("test_id"),
                secret,
                metadata.get("attempt_id").toString(),
                null,
                null,
                null,
                null);
        Instant at = ((Timestamp) metadata.get("occurred_at")).toInstant();
        append(
            scope,
            row(
                scope,
                identity(
                    usage == UsageOutcome.NOT_USED ? "unattempted" : "terminal-uncertain",
                    scope,
                    null),
                at,
                at,
                "USAGE",
                null,
                null,
                null,
                null,
                null,
                usage));
      }
    return true;
  }

  private Map<String, Object> observedMetadata(JsonNode binding, String leaseOwner) {
    requireTransaction();
    bounded(leaseOwner, 256);
    if (binding == null || !binding.isObject()) throw invalid();
    final UUID execution;
    final Instant accepted;
    final UUID attempt;
    try {
      execution = UUID.fromString(binding.path("executionId").asText());
      accepted = Instant.parse(binding.path("startedAt").asText());
      attempt = UUID.fromString(binding.path("attemptId").asText());
    } catch (RuntimeException invalidIdentity) {
      throw invalid();
    }
    var rows =
        jdbc.queryForList(
            "SELECT l.execution_id,l.execution_accepted_at,e.observed_revision_binding::text AS accepted_binding,CAST(e.observed_revision_binding->>'attemptId' AS uuid) AS attempt_id,e.revision_id,e.observed_revision_binding->>'revisionDigest' AS revision_digest,studio_publication_hash(e.observed_revision_binding) AS binding_digest,e.observed_revision_binding->>'scopeHash' AS scope_hash,l.principal AS principal_id,l.csi_id,e.environment,l.test_id,l.lease_owner FROM studio_dispatch_ledger l JOIN ui_test_executions e ON e.id=l.execution_id AND e.started_at=l.execution_accepted_at WHERE l.execution_id=? AND l.execution_accepted_at=? AND l.state='CLAIMED' AND l.lease_owner=? AND l.lease_expires_at>clock_timestamp() AND l.attempt_id IS NULL AND l.admission_id IS NULL AND e.observed_admission_receipt IS NULL AND e.observed_revision_binding->>'attemptId'=? FOR UPDATE OF l,e",
            execution,
            Timestamp.from(accepted),
            leaseOwner,
            attempt.toString());
    if (rows.size() != 1) throw invalid();
    if (Boolean.TRUE.equals(
        jdbc.queryForObject(
            "SELECT EXISTS(SELECT 1 FROM studio_observed_terminal_secret_settlements WHERE execution_id=?)",
            Boolean.class,
            execution))) throw invalid();
    var result = new LinkedHashMap<>(rows.getFirst());
    if (!binding.equals(new GuidedContracts().parse((String) result.remove("accepted_binding"))))
      throw invalid();
    return result;
  }

  private Map<String, Object> append(Scope scope, Map<String, Object> row) {
    requireTransaction();
    // Match the raw SQL guard: owner row, owner advisory, then event advisory.
    if (scope.path() == Path.GUIDED)
      jdbc.queryForObject(
          "SELECT session_id FROM studio_guided_sessions WHERE session_id=? FOR UPDATE",
          String.class,
          scope.sessionId());
    else
      jdbc.queryForObject(
          "SELECT execution_id FROM studio_dispatch_ledger WHERE execution_id=? FOR UPDATE",
          UUID.class,
          scope.executionId());
    String owner =
        "studio-secret-audit-owner:"
            + scope.path()
            + ":"
            + (scope.sessionId() != null ? scope.sessionId() : scope.executionId());
    jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))", rs -> {}, owner);
    jdbc.query(
        "SELECT pg_advisory_xact_lock(hashtextextended(?,0))",
        rs -> {},
        "studio-secret-audit-id:" + row.get("id"));
    List<Map<String, Object>> existing =
        jdbc.queryForList(
            "SELECT " + String.join(",", COLUMNS) + " FROM studio_secret_use_audit WHERE id=?",
            row.get("id"));
    if (!existing.isEmpty()) {
      Map<String, Object> stored = existing.getFirst();
      for (String column : COLUMNS) {
        if (column.equals("occurred_at")
            || column.equals("release_occurred_at") && row.get("release_id") == null) continue;
        if (column.equals("release_occurred_at") && "DISPATCH".equals(row.get("decision_stage")))
          continue;
        if (column.equals("usage_outcome")
            && ("UNKNOWN_OUTCOME".equals(row.get(column)) || "ACK_LOST".equals(row.get(column)))
            && stored.get(column) != null
            && List.of(
                    "USED",
                    "NOT_USED",
                    "REFUSED",
                    "OK",
                    "ASSERTION_FAILED",
                    "TARGET_CHANGED",
                    "POLICY_DENIED",
                    "TIMEOUT",
                    "CANCELLED")
                .contains(stored.get(column))) continue;
        if (!Objects.equals(stored.get(column), row.get(column)))
          throw new IllegalStateException("Conflicting secret audit event");
      }
      return stored;
    }
    named.update(
        "INSERT INTO studio_secret_use_audit ("
            + String.join(",", COLUMNS)
            + ") VALUES ("
            + String.join(",", COLUMNS.stream().map(c -> ":" + c).toList())
            + ")",
        row);
    return row;
  }

  private static Map<String, Object> row(
      Scope s,
      UUID id,
      Instant occurred,
      Instant lifecycle,
      String kind,
      UUID release,
      UUID affected,
      String stage,
      String version,
      ResolutionOutcome outcome,
      UsageOutcome usage) {
    Map<String, Object> r = new LinkedHashMap<>();
    r.put("id", id);
    r.put("occurred_at", Timestamp.from(occurred));
    r.put("release_occurred_at", Timestamp.from(lifecycle));
    r.put("path", s.path().name());
    r.put("row_kind", kind);
    r.put("release_id", release);
    r.put("affected_release_id", affected);
    r.put("decision_stage", stage);
    r.put("attempt_id", s.attemptId());
    r.put("release_seq", s.releaseSeq());
    r.put("execution_id", s.executionId());
    r.put("session_id", s.sessionId());
    r.put("admission_id", s.admissionId());
    r.put("principal_id", s.principalId());
    r.put("csi_id", s.csiId());
    r.put("environment", s.environment());
    r.put("test_id", s.testId());
    r.put("secret_id", s.secretId());
    r.put("vault_version", version);
    r.put("coordinate_step_id", s.coordinateStepId());
    r.put("coordinate_ordinal", s.coordinateOrdinal());
    r.put("source_reference_id", s.sourceReferenceId());
    r.put("outcome", outcome == null ? null : outcome.name());
    r.put("usage_outcome", usage == null ? null : usage.name());
    return r;
  }

  private Instant now() {
    return clock.instant().truncatedTo(ChronoUnit.MICROS);
  }

  private static UUID identity(String event, Scope s, UUID release) {
    String text =
        event
            + "|"
            + s.path()
            + "|"
            + s.executionId()
            + "|"
            + s.sessionId()
            + "|"
            + s.attemptId()
            + "|"
            + s.secretId()
            + "|"
            + s.coordinateStepId()
            + "|"
            + s.coordinateOrdinal()
            + "|"
            + s.releaseSeq()
            + (event.equals("unreached") ? "|" + s.sourceReferenceId() : "")
            + "|"
            + release;
    return UUID.nameUUIDFromBytes(text.getBytes(StandardCharsets.UTF_8));
  }

  private static void requireTransaction() {
    if (!TransactionSynchronizationManager.isActualTransactionActive())
      throw new IllegalStateException("Secret audit requires the dispatch transaction");
  }

  private static void bounded(String value, int bound) {
    if (value == null || value.isBlank() || value.length() > bound) throw invalid();
  }

  private static IllegalArgumentException invalid() {
    return new IllegalArgumentException("Invalid secret audit metadata");
  }
}

package com.citi.put.checks.studio.secrets;

import com.citi.put.checks.studio.guided.session.GuidedContracts;
import com.fasterxml.jackson.databind.JsonNode;
import java.sql.Timestamp;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/**
 * Joins safe source/admission/execution facts to append-only audit events in caller transactions.
 */
@Component
public final class SecretAuditLifecycle {
  private final JdbcTemplate jdbc;
  private final SecretUseAuditRecorder audit;

  public SecretAuditLifecycle(JdbcTemplate jdbc, SecretUseAuditRecorder audit) {
    this.jdbc = jdbc;
    this.audit = audit;
  }

  public SecretUseAuditRecorder.Release guidedRelease(
      JsonNode session,
      JsonNode action,
      String secretId,
      String version,
      SecretUseAuditRecorder.ResolutionOutcome outcome) {
    JsonNode scope = session.path("scope"), coordinate = action.path("coordinate");
    String id = session.path("sessionId").asText();
    long sequence = nextSequence("session_id", id, secretId, coordinate.path("stepId").asText());
    var identity =
        new SecretUseAuditRecorder.Scope(
            SecretUseAuditRecorder.Path.GUIDED,
            null,
            id,
            action.path("admission").path("admissionId").asText(),
            scope.path("principalId").asText(),
            scope.path("csiId").asText(),
            scope.path("environmentId").asText(),
            UUID.fromString(session.path("testId").asText()),
            secretId,
            id + ":" + action.path("ownerFence").asText(),
            sequence,
            coordinate.path("stepId").asText(),
            coordinate.path("ordinal").asInt(),
            guidedReferenceId(
                id,
                action.path("admission").path("admissionId").asText(),
                secretId,
                coordinate.path("stepId").asText()));
    return audit.recordRelease(identity, version, outcome);
  }

  public void guidedOutcome(JsonNode session, JsonNode action) {
    for (var row :
        jdbc.queryForList(
            "SELECT * FROM studio_secret_use_audit WHERE session_id=? AND admission_id=? AND decision_stage='DISPATCH'",
            session.path("sessionId").asText(),
            action.path("admission").path("admissionId").asText())) {
      String code = action.path("outcomeCode").asText();
      audit.recordUsage(
          release(row),
          code.equals("OK")
              ? SecretUseAuditRecorder.UsageOutcome.USED
              : SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
    }
  }

  public void guidedTerminal(JsonNode session) {
    String id = session.path("sessionId").asText();
    for (var row :
        jdbc.queryForList(
            "SELECT a.*,g.document::text AS action FROM studio_secret_use_audit a JOIN studio_guided_actions g ON g.session_id=a.session_id AND g.admission_id=a.admission_id WHERE a.session_id=? AND a.decision_stage='DISPATCH' AND NOT EXISTS(SELECT 1 FROM studio_secret_use_audit u WHERE u.release_id=a.id AND u.row_kind='USAGE')",
            id)) {
      JsonNode action = new GuidedContracts().parse((String) row.get("action"));
      String code = action.path("outcomeCode").asText();
      SecretUseAuditRecorder.UsageOutcome usage =
          code.equals("OK")
              ? SecretUseAuditRecorder.UsageOutcome.USED
              : SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME;
      audit.recordUsage(release(row), usage);
    }
    var manifests =
        jdbc.queryForList(
            "SELECT manifest::text FROM studio_guided_source_manifests WHERE session_id=?",
            String.class,
            id);
    if (manifests.isEmpty()) return;
    JsonNode scope = session.path("scope");
    JsonNode manifest = new GuidedContracts().parse(manifests.getFirst());
    var consumed =
        jdbc.queryForList(
            "SELECT g.document::text AS action,g.proposal::text AS proposal,m.authored_inputs::text AS inputs FROM studio_guided_actions g JOIN studio_guided_materializations m ON m.session_id=g.session_id WHERE g.session_id=? AND (g.document->>'dispatchCount')::integer=1 AND g.proposal->'operation'->>'kind'='fill' AND g.proposal->'operation'->'value'->>'kind'='secretRef'",
            id);
    for (JsonNode reference : manifest.path("configurationReferences")) {
      if (!reference.path("kind").asText().equals("secretRef")) continue;
      String secret = reference.path("referenceName").asText();
      String step = reference.path("stepId").asText();
      String referenceId = reference.path("referenceId").asText();
      if (referenceId.isBlank())
        throw new IllegalStateException("Missing source reference identity");
      var matching = new java.util.ArrayList<JsonNode>();
      for (var admission : consumed) {
        JsonNode proposal = new GuidedContracts().parse((String) admission.get("proposal"));
        JsonNode action = new GuidedContracts().parse((String) admission.get("action"));
        for (JsonNode input :
            new GuidedContracts().parse((String) admission.get("inputs")).path("inputs")) {
          if (input
                  .path("inputId")
                  .equals(proposal.path("operation").path("value").path("sourceInputId"))
              && input.path("kind").asText().equals("secretRef")
              && input.path("secretId").asText().equals(secret)
              && input.path("sourceStepId").asText().equals(step)
              && input.path("intendedSlot").asText().equals("fill.value")
              && input.path("provenance").path("referenceId").asText().equals(referenceId)
              && action.path("coordinate").path("stepId").asText().equals(step))
            matching.add(action);
        }
      }
      if (matching.isEmpty()) {
        Integer summaries =
            jdbc.queryForObject(
                "SELECT count(*) FROM studio_secret_use_audit WHERE session_id=? AND source_reference_id=? AND row_kind='USAGE'",
                Integer.class,
                id,
                referenceId);
        if (summaries != null && summaries > 0) continue;
        audit.recordUnreachedGuided(
            new SecretUseAuditRecorder.Scope(
                SecretUseAuditRecorder.Path.GUIDED,
                null,
                id,
                null,
                scope.path("principalId").asText(),
                scope.path("csiId").asText(),
                scope.path("environmentId").asText(),
                UUID.fromString(session.path("testId").asText()),
                secret,
                id + ":" + session.path("owner").path("fence").asText(),
                null,
                step,
                null,
                referenceId));
      } else {
        for (JsonNode actual : matching) {
          String admissionId = actual.path("admission").path("admissionId").asText();
          Integer existing =
              jdbc.queryForObject(
                  "SELECT count(*) FROM studio_secret_use_audit WHERE session_id=? AND admission_id=? AND row_kind='USAGE'",
                  Integer.class,
                  id,
                  admissionId);
          if (existing != null && existing > 0) continue;
          audit.recordConsumedNoDecision(
              new SecretUseAuditRecorder.Scope(
                  SecretUseAuditRecorder.Path.GUIDED,
                  null,
                  id,
                  admissionId,
                  scope.path("principalId").asText(),
                  scope.path("csiId").asText(),
                  scope.path("environmentId").asText(),
                  UUID.fromString(session.path("testId").asText()),
                  secret,
                  id + ":" + actual.path("ownerFence").asText(),
                  null,
                  actual.path("coordinate").path("stepId").asText(),
                  actual.path("coordinate").path("ordinal").asInt(),
                  referenceId),
              SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
        }
      }
    }
  }

  private String guidedReferenceId(
      String sessionId, String admissionId, String secretId, String stepId) {
    var rows =
        jdbc.queryForList(
            "SELECT g.proposal::text AS proposal,m.authored_inputs::text AS inputs FROM studio_guided_actions g JOIN studio_guided_materializations m ON m.session_id=g.session_id WHERE g.session_id=? AND g.admission_id=?",
            sessionId,
            admissionId);
    var ids = new java.util.HashSet<String>();
    for (var row : rows) {
      JsonNode proposal = new GuidedContracts().parse((String) row.get("proposal"));
      for (JsonNode input :
          new GuidedContracts().parse((String) row.get("inputs")).path("inputs")) {
        if (input
                .path("inputId")
                .equals(proposal.path("operation").path("value").path("sourceInputId"))
            && input.path("kind").asText().equals("secretRef")
            && input.path("secretId").asText().equals(secretId)
            && input.path("sourceStepId").asText().equals(stepId)
            && input.path("intendedSlot").asText().equals("fill.value"))
          ids.add(input.path("provenance").path("referenceId").asText());
      }
    }
    if (ids.size() != 1 || ids.contains(""))
      throw new IllegalStateException("Missing consumed source reference identity");
    return ids.iterator().next();
  }

  /** Only backend decisions made before a secret frame can enter transport may use this path. */
  public void guidedNoSend(JsonNode session, JsonNode action) {
    for (var row :
        jdbc.queryForList(
            "SELECT * FROM studio_secret_use_audit WHERE session_id=? AND admission_id=? AND decision_stage='DISPATCH'",
            session.path("sessionId").asText(),
            action.path("admission").path("admissionId").asText()))
      audit.recordUsage(release(row), SecretUseAuditRecorder.UsageOutcome.REFUSED);
  }

  public boolean replayTerminalSettlement(
      UUID execution, String plannedErrorCode, java.time.Instant plannedEndedAt) {
    return audit.recordObservedTerminalSettlement(execution, plannedErrorCode, plannedEndedAt);
  }

  public void replayReadEntry(JsonNode binding, String leaseOwner, String secretId) {
    audit.recordObservedReadEntry(binding, leaseOwner, secretId);
  }

  public void replayNoSendDecision(
      JsonNode binding,
      String leaseOwner,
      java.util.Set<String> notEntered,
      SecretUseAuditRecorder.NoSendDisposition disposition) {
    var proven = new java.util.LinkedHashSet<>(notEntered);
    proven.removeAll(
        jdbc.queryForList(
            "SELECT secret_id FROM studio_observed_secret_read_entries WHERE execution_id=? AND attempt_id=?",
            String.class,
            UUID.fromString(binding.path("executionId").asText()),
            UUID.fromString(binding.path("attemptId").asText())));
    audit.recordObservedNoSend(binding, leaseOwner, proven, disposition);
  }

  /** An authoritative terminal owner cannot infer effects from an absent child report. */
  public void replayOwnerTerminal(UUID execution) {
    replayDecision(execution, null, SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
  }

  /** Called only with actual failed resolution or an authoritative runner no-admission refusal. */
  public void replayNoSend(UUID execution, UUID attempt) {
    replayDecision(execution, attempt, SecretUseAuditRecorder.UsageOutcome.REFUSED);
  }

  private void replayDecision(
      UUID execution, UUID attempt, SecretUseAuditRecorder.UsageOutcome usage) {
    for (var row :
        jdbc.queryForList(
            "SELECT a.* FROM studio_secret_use_audit a WHERE a.execution_id=? AND (?::text IS NULL OR a.attempt_id=?::text) AND a.decision_stage='DISPATCH' AND NOT EXISTS (SELECT 1 FROM studio_secret_use_audit u WHERE u.release_id=a.id AND u.row_kind='USAGE')",
            execution,
            attempt == null ? null : attempt.toString(),
            attempt == null ? null : attempt.toString())) audit.recordUsage(release(row), usage);
  }

  public void replayRelease(
      JsonNode binding,
      List<String> ids,
      Map<String, String> versions,
      SecretUseAuditRecorder.ResolutionOutcome outcome) {
    UUID execution = UUID.fromString(binding.path("executionId").asText());
    for (String id : ids)
      audit.recordRelease(
          new SecretUseAuditRecorder.Scope(
              SecretUseAuditRecorder.Path.OBSERVED_REPLAY,
              execution,
              null,
              null,
              binding.path("principalId").asText(),
              binding.path("csiId").asText(),
              binding.path("environment").asText(),
              UUID.fromString(binding.path("testId").asText()),
              id,
              binding.path("attemptId").asText(),
              nextSequence("execution_id", execution, id, null),
              null,
              null),
          versions.get(id),
          outcome);
  }

  public void replayKnownUses(UUID execution, UUID attempt, Map<String, String> usage) {
    if (usage.isEmpty()) return;
    if (usage.values().stream().anyMatch(value -> !"USED".equals(value)))
      throw new IllegalArgumentException("Invalid positive secret usage report");
    var releases =
        jdbc.queryForList(
            "SELECT * FROM studio_secret_use_audit WHERE execution_id=? AND attempt_id=? AND decision_stage='DISPATCH' AND outcome='RESOLVED'",
            execution,
            attempt.toString());
    var available = new java.util.HashSet<String>();
    releases.forEach(row -> available.add((String) row.get("secret_id")));
    if (!available.containsAll(usage.keySet()))
      throw new IllegalArgumentException("Missing scoped resolved secret release");
    for (var row : releases)
      if (usage.containsKey((String) row.get("secret_id")))
        audit.recordUsage(release(row), SecretUseAuditRecorder.UsageOutcome.USED);
  }

  public void replayTerminal(UUID execution, UUID attempt, Map<String, String> usage) {
    var rows =
        jdbc.queryForList(
            "SELECT * FROM studio_secret_use_audit WHERE execution_id=? AND attempt_id=? AND decision_stage='DISPATCH'",
            execution,
            attempt.toString());
    var declared = new java.util.HashSet<String>();
    rows.forEach(row -> declared.add((String) row.get("secret_id")));
    if (!declared.containsAll(usage.keySet()))
      throw new IllegalArgumentException("Invalid secret usage report");
    for (var row : rows)
      audit.recordUsage(
          release(row),
          usage.containsKey((String) row.get("secret_id"))
              ? SecretUseAuditRecorder.UsageOutcome.valueOf(
                  usage.get((String) row.get("secret_id")))
              : SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
  }

  private long nextSequence(String ownerColumn, Object id, String secret, String step) {
    Long count =
        jdbc.queryForObject(
            "SELECT COALESCE(max(release_seq),0)+1 FROM studio_secret_use_audit WHERE "
                + ownerColumn
                + "=? AND secret_id=? AND coordinate_step_id IS NOT DISTINCT FROM ? AND decision_stage='DISPATCH'",
            Long.class,
            id,
            secret,
            step);
    return count == null ? 1 : count;
  }

  public static SecretUseAuditRecorder.Release release(Map<String, Object> row) {
    var scope =
        new SecretUseAuditRecorder.Scope(
            SecretUseAuditRecorder.Path.valueOf((String) row.get("path")),
            (UUID) row.get("execution_id"),
            (String) row.get("session_id"),
            (String) row.get("admission_id"),
            (String) row.get("principal_id"),
            (String) row.get("csi_id"),
            (String) row.get("environment"),
            (UUID) row.get("test_id"),
            (String) row.get("secret_id"),
            (String) row.get("attempt_id"),
            ((Number) row.get("release_seq")).longValue(),
            (String) row.get("coordinate_step_id"),
            (Integer) row.get("coordinate_ordinal"),
            (String) row.get("source_reference_id"));
    return new SecretUseAuditRecorder.Release(
        (UUID) row.get("id"),
        ((Timestamp) row.get("release_occurred_at")).toInstant(),
        scope,
        (String) row.get("vault_version"),
        SecretUseAuditRecorder.ResolutionOutcome.valueOf((String) row.get("outcome")));
  }
}

