package com.citi.put.checks.studio.dispatch;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * The one seam through which a declared variable or secret reference becomes a value (§5.1.1,
 * §5.1.3, §9.2).
 *
 * <p>Two operations, deliberately separated, because §5.1.1 and §5.1.3 place them at different
 * points in the lifecycle and the separation is the security property:
 *
 * <ul>
 *   <li>{@link #preflight} runs at <b>acceptance</b> and resolves nothing that outlives the call.
 *       It checks that the declared names are references this CSI, environment and principal are
 *       permitted to use. An unknown or unpermitted reference is a {@code 400} naming the reference
 *       and never its value.
 *   <li>{@link #resolve} runs at <b>dispatch</b>, immediately before the send, and nowhere else.
 *       The values it returns are ephemeral: they are never written to the ledger, the history row,
 *       a log line, a retry buffer, a manifest or an SSE payload, and they are cleared on every
 *       exit path including the error path — which is what {@link Resolved} being {@link
 *       AutoCloseable} is for.
 * </ul>
 *
 * <p><b>Typed, since story 10.17.</b> Both operations take the revision's {@link
 * ReferenceDeclarations} rather than a flat list, because a secret and a variable are different
 * decisions: a secret's use is authorized separately (§9.2, <em>"Secret reference names alone grant
 * no permission"</em>) and the two resolved maps the contract declares cannot be filled from one
 * undifferentiated set.
 *
 * <p>Real vault integration and real per-principal entitlement are {@code ED-02} and story 10.18.
 * What ships here is the seam and the real provider integration; test doubles and canaries prove
 * values do not leak.
 */
public interface StudioReferenceResolver {

  /**
   * Names only, at acceptance. Retains nothing.
   *
   * @param csiId the test's CSI
   * @param environment the test's environment, which the execution snapshots
   * @param testId the test the references were declared by; references are scoped to it
   * @throws UnknownReferenceException when a name is unknown to this CSI/environment/test
   * @throws SecretUseNotAuthorizedException when the principal may not use a declared secret
   */
  void preflight(
      String csiId,
      String environment,
      UUID testId,
      String principal,
      ReferenceDeclarations declarations);

  /**
   * Values, at dispatch only.
   *
   * @param csiId the execution's own CSI
   * @param environment the environment snapshotted at acceptance
   * @param testId the execution row's {@code test_id}
   * @throws ReferenceUnavailableException for a reference that has vanished since acceptance
   * @throws SecretUseRevokedException when entitlement was withdrawn since acceptance
   */
  Resolved resolve(
      String csiId,
      String environment,
      UUID testId,
      String principal,
      ReferenceDeclarations declarations);

  @FunctionalInterface
  interface ValueReadEntry {
    void beforeRead(String secretId);
  }

  /** The actual provider implementation must place the observer before each value-read entry. */
  default Resolved resolve(String csiId, String environment, UUID testId, String principal,
      ReferenceDeclarations declarations, ValueReadEntry entry) {
    throw new IllegalStateException("Reference resolver does not provide tracked value-read entry");
  }

  enum DecisionOutcome { RESOLVED, NOT_AUTHORIZED, REVOKED, UNAVAILABLE, VAULT_UNAVAILABLE }

  /** Safe dispatch decision metadata; no value, value digest, request body or original error. */
  record Decision(DecisionOutcome outcome, String version) {
    public Decision {
      java.util.Objects.requireNonNull(outcome);
      if (version != null && (version.isBlank() || version.length() > 256))
        throw new IllegalArgumentException("Invalid resolution version metadata");
      if (outcome == DecisionOutcome.RESOLVED && version == null)
        throw new IllegalArgumentException("Missing resolution version metadata");
    }
  }

  final class ResolutionFacts extends RuntimeException {
    private static final long serialVersionUID = 1L;
    private final Map<String, Decision> decisions;
    private final java.util.Set<String> positivelyNotEntered;
    private ResolutionFacts(Map<String, Decision> decisions, java.util.Set<String> positivelyNotEntered) {
      super("Safe secret resolution decisions", null, false, false);
      this.decisions = Map.copyOf(decisions);
      this.positivelyNotEntered = java.util.Set.copyOf(positivelyNotEntered);
      if (this.positivelyNotEntered.stream().anyMatch(decisions::containsKey)) throw new IllegalArgumentException("Contradictory resolution evidence");
    }
    public java.util.Set<String> positivelyNotEntered() { return positivelyNotEntered; }
    public Map<String, Decision> decisions() { return decisions; }
  }

  static void attachDecisionFacts(RuntimeException failure, Map<String, Decision> decisions) {
    attachDecisionFacts(failure, decisions, java.util.Set.of());
  }

  static void attachDecisionFacts(RuntimeException failure, Map<String, Decision> decisions,
      java.util.Set<String> positivelyNotEntered) {
    if (!decisions.isEmpty() || !positivelyNotEntered.isEmpty())
      failure.addSuppressed(new ResolutionFacts(decisions, positivelyNotEntered));
  }

  static java.util.Set<String> positivelyNotEntered(Throwable failure) {
    for (Throwable item : failure.getSuppressed())
      if (item instanceof ResolutionFacts facts) return facts.positivelyNotEntered();
    return java.util.Set.of();
  }

  static Map<String, Decision> decisionFacts(Throwable failure) {
    for (Throwable item : failure.getSuppressed())
      if (item instanceof ResolutionFacts facts) return facts.decisions();
    return Map.of();
  }

  /** A declared reference this CSI may not use, or that does not exist. Never carries a value. */
  class UnknownReferenceException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    private final String referenceName;

    public UnknownReferenceException(String referenceName) {
      super("Reference '" + referenceName + "' is not a reference this CSI may use");
      this.referenceName = referenceName;
    }

    public String getReferenceName() {
      return referenceName;
    }
  }

  /**
   * The principal is not entitled to use this secret, observed at <b>acceptance</b> (AC-4).
   *
   * <p>Separate from {@link UnknownReferenceException} because the two are different facts and a
   * refusal that conflated them would tell an unentitled caller whether the secret exists.
   * Deliberately carries the same wording for that reason; only the type differs, and the type is
   * not on the wire.
   */
  class SecretUseNotAuthorizedException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    private final String referenceName;

    public SecretUseNotAuthorizedException(String referenceName) {
      super("Reference '" + referenceName + "' is not a reference this CSI may use");
      this.referenceName = referenceName;
    }

    public String getReferenceName() {
      return referenceName;
    }
  }

  /**
   * Entitlement to a declared secret was withdrawn between acceptance and <b>dispatch</b> (AC-7a).
   *
   * <p>ADR-002 §15.2's axis: this is <em>a fact about the principal</em>, so the dispatcher closes
   * it {@code AUTHORIZATION_REVOKED}. A vanished reference is a fact about the draft and its
   * environment and is {@link ReferenceUnavailableException} instead. Both mean the send never
   * happened.
   */
  class SecretUseRevokedException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    private final String referenceName;

    public SecretUseRevokedException(String referenceName) {
      super("Use of reference '" + referenceName + "' is no longer authorized at dispatch");
      this.referenceName = referenceName;
    }

    public String getReferenceName() {
      return referenceName;
    }
  }

  /** A reference that existed at preflight and does not exist at dispatch (AC-7a). */
  class ReferenceUnavailableException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    private final String referenceName;

    public ReferenceUnavailableException(String referenceName) {
      super("Reference '" + referenceName + "' is no longer available at dispatch");
      this.referenceName = referenceName;
    }

    public String getReferenceName() {
      return referenceName;
    }
  }

  /**
   * Resolved values, held as {@code char[]} so that {@link #close()} can actually erase them rather
   * than leaving an interned {@link String} on the heap until a collection it cannot force.
   *
   * <p>Two maps, because the contract declares two and because only one of them is a secret. Both
   * are erased by {@link #close()}: §9.2's <em>"Never persist them in jobs, retry queues, manifests
   * or diagnostics"</em> governs <em>resolved values</em>, and a variable is author-supplied free
   * text the system knows nothing about. The runner scrubs both for the same reason (@po ruling on
   * Open Question 2, 2026-09-11).
   *
   * <p><b>The residual, stated rather than implied (AC-15).</b> The moment these arrays are
   * serialized into a JSON body the platform creates {@link String}s that no code can erase. The
   * decidable property — and the only one claimed — is that nothing in this process retains a
   * <em>path</em> to the values once {@link #close()} has run. The serializer's transient buffers
   * are the named residual.
   */
  final class Resolved implements AutoCloseable {

    private final Map<String, char[]> variables;
    private final Map<String, char[]> secrets;
    private final Map<String, String> secretVersions;
    private final Map<String, List<String>> secretOrigins;

    public Resolved(
        Map<String, char[]> variables,
        Map<String, char[]> secrets,
        Map<String, String> secretVersions) {
      this(variables, secrets, secretVersions, Map.of());
    }

    public Resolved(
        Map<String, char[]> variables,
        Map<String, char[]> secrets,
        Map<String, String> secretVersions,
        Map<String, List<String>> secretOrigins) {
      this.variables = new LinkedHashMap<>(variables);
      this.secrets = new LinkedHashMap<>(secrets);
      this.secretVersions = new LinkedHashMap<>(secretVersions);
      this.secretOrigins = new LinkedHashMap<>();
      secretOrigins.forEach((id, origins) -> this.secretOrigins.put(id, List.copyOf(origins)));
    }

    public Map<String, char[]> variables() {
      return Map.copyOf(variables);
    }

    /** Owned wrappers share this resolution's arrays; close erases every path. */
    public Map<String, com.citi.put.checks.studio.secrets.SecretValue> secretValues() {
      var result = new LinkedHashMap<String, com.citi.put.checks.studio.secrets.SecretValue>();
      secrets.forEach(
          (id, value) -> result.put(id, new com.citi.put.checks.studio.secrets.SecretValue(value)));
      return Map.copyOf(result);
    }

    public Map<String, char[]> secrets() {
      return Map.copyOf(secrets);
    }

    /**
     * The nonsecret opaque version identifier each resolved secret was read at (§4.2, AC-8).
     *
     * <p>Supplied by the provider. Never the value, never a hash of the value, and never anything a
     * caller could use to compare two values: rotating a value <em>to itself</em> still changes the
     * identifier, which is what stops it becoming an oracle.
     */
    public Map<String, String> secretVersions() {
      return Map.copyOf(secretVersions);
    }

    /**
     * The normalized origins each resolved secret may be filled on, as its vault entry declares
     * them. Nonsecret. A secret with no entry here, or an empty list, is bound to no origin and the
     * runner refuses to fill it.
     */
    public Map<String, List<String>> secretOrigins() {
      return Map.copyOf(secretOrigins);
    }

    public boolean isEmpty() {
      return variables.isEmpty() && secrets.isEmpty();
    }

    @Override
    public void close() {
      variables.values().forEach(value -> Arrays.fill(value, '\0'));
      secrets.values().forEach(value -> Arrays.fill(value, '\0'));
      variables.clear();
      secrets.clear();
      secretVersions.clear();
      secretOrigins.clear();
    }
  }
}

package com.citi.put.checks.studio.secrets;

import com.citi.put.checks.studio.dispatch.ReferenceDeclarations;
import com.citi.put.checks.studio.dispatch.StudioReferenceResolver;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import org.springframework.stereotype.Component;

/**
 * The vault-backed resolver that replaces {@code StubStudioReferenceResolver} (AC-1, AC-4, AC-5a,
 * AC-7a).
 *
 * <p>History: the stub it replaced answered its two questions against the former global platform
 * {@code secrets} table (dropped by V25) and <b>never read its {@code csiId} parameter at all</b>,
 * so any CSI could name any secret; and it returned a configured canary string for every name, so
 * no real value had ever reached a runner. Both are gone. Vault is now the only secret store.
 *
 * <p>Three properties, all of them AC-5a's and all decidable on this branch without inventing an
 * entitlement model:
 *
 * <ul>
 *   <li>the resolvable set is the <b>confirmed revision's</b> typed declaration, handed in by the
 *       caller — never the draft's current {@code variables} and never the request;
 *   <li>the CSI is the <b>execution's own immutable</b> {@code csi_id}, so editing or moving the
 *       parent draft between acceptance and dispatch changes nothing;
 *   <li>the environment is the one snapshotted at acceptance, so a reference entitled only in
 *       {@code dev} is simply absent for a {@code prod} execution;
 *   <li>the test id scopes every read ({@link VaultScope}), so a secret saved for one test is
 *       absent for another test with the same CSI and environment.
 * </ul>
 *
 * <p>A declared secret id that is not a valid secret name ({@link
 * StudioVaultProvider#isValidSecretName}), such as a legacy {@code vault://…} id, is refused as an
 * unknown (acceptance) or unavailable (dispatch) reference <b>before</b> the provider is called.
 * Otherwise the provider's path-safety check would report it as a Vault outage.
 *
 * <p>Secret use is a decision of its own (§9.2): {@link StudioSecretUseAuthorization} is consulted
 * <b>separately</b> from {@code CsiOwnershipEvaluator}, per secret, and a principal who owns the
 * CSI can still be refused a secret it names. The principal dimension of the <em>real</em> vault's
 * policy is AC-5b and `ED-02`'s.
 *
 * <p><b>Secret preflight reads names only.</b> Authorization and the scoped name list prove the
 * declaration exists without reading its value. Legacy variable preflight erases every array it
 * reads, including on refusal.
 */
@Component
public class VaultStudioReferenceResolver implements StudioReferenceResolver {

  private final StudioVaultProvider vault;
  private final StudioSecretUseAuthorization secretUse;

  public VaultStudioReferenceResolver(
      StudioVaultProvider vault, StudioSecretUseAuthorization secretUse) {
    this.vault = vault;
    this.secretUse = secretUse;
  }

  @Override
  public void preflight(
      String csiId,
      String environment,
      UUID testId,
      String principal,
      ReferenceDeclarations declarations) {
    refuseCrossedNames(declarations, false);
    VaultScope scope = VaultScope.of(csiId, environment, testId);

    for (String name : declarations.variables()) {
      requireName(name);
      erase(
          vault
              .read(StudioVaultProvider.ReferenceKind.VARIABLE, scope, name)
              .orElseThrow(() -> new UnknownReferenceException(name)));
    }
    for (String secretId : declarations.secrets()) {
      requireName(secretId);
      if (!StudioVaultProvider.isValidSecretName(secretId)) {
        throw new UnknownReferenceException(secretId);
      }
      if (!secretUse.mayUse(principal, csiId, environment, secretId)) {
        // A name grants nothing (§9.2). The refusal names the reference and never the value.
        throw new SecretUseNotAuthorizedException(secretId);
      }
      if (!vault.listSecretNames(scope).contains(secretId))
        throw new UnknownReferenceException(secretId);
    }
  }

  @Override
  public Resolved resolve(
      String csiId,
      String environment,
      UUID testId,
      String principal,
      ReferenceDeclarations declarations) {
    return resolve(csiId,environment,testId,principal,declarations,id -> {});
  }

  @Override
  public Resolved resolve(String csiId,String environment,UUID testId,String principal,
      ReferenceDeclarations declarations,ValueReadEntry entryObserver) {
    refuseCrossedNames(declarations, true);
    VaultScope scope = VaultScope.of(csiId, environment, testId);

    Map<String, char[]> variables = new LinkedHashMap<>();
    Map<String, char[]> secrets = new LinkedHashMap<>();
    Map<String, String> versions = new LinkedHashMap<>();
    Map<String, List<String>> origins = new LinkedHashMap<>();
    Map<String, Decision> decisions = new LinkedHashMap<>();
    String currentSecret = null;
    var entered = new java.util.LinkedHashSet<String>();
    try {
      for (String name : declarations.variables()) {
        StudioVaultProvider.VaultEntry entry =
            vault
                .read(StudioVaultProvider.ReferenceKind.VARIABLE, scope, name)
                .orElseThrow(() -> new ReferenceUnavailableException(name));
        variables.put(name, entry.value());
      }
      for (String secretId : declarations.secrets()) {
        currentSecret = secretId;
        if (!StudioVaultProvider.isValidSecretName(secretId)) {
          throw new ReferenceUnavailableException(secretId);
        }
        // The recheck §5.1.3 asks for: entitlement is re-evaluated at dispatch, not inherited from
        // the acceptance that happened before an unbounded queue wait.
        if (!secretUse.mayUse(principal, csiId, environment, secretId)) {
          throw new SecretUseRevokedException(secretId);
        }
        entryObserver.beforeRead(secretId);
        entered.add(secretId);
        StudioVaultProvider.VaultEntry entry =
            vault
                .read(StudioVaultProvider.ReferenceKind.SECRET, scope, secretId)
                .orElseThrow(() -> new ReferenceUnavailableException(secretId));
        if (entry.value()==null || entry.versionIdentifier()==null || entry.versionIdentifier().isBlank() || entry.versionIdentifier().length()>256) {
          if(entry.value()!=null) Arrays.fill(entry.value(),'\0');throw new ReferenceUnavailableException(secretId);
        }
        if (entry.value().length == 0) { Arrays.fill(entry.value(),'\0');throw new ReferenceUnavailableException(secretId); }
        if (entry.value().length > 4096) {
          Arrays.fill(entry.value(), '\0');
          throw new SecretTooLongException(secretId);
        }
        secrets.put(secretId, entry.value());
        versions.put(secretId, entry.versionIdentifier());
        origins.put(secretId, entry.allowedOrigins());
        decisions.put(secretId, new Decision(DecisionOutcome.RESOLVED, entry.versionIdentifier()));
        currentSecret = null;
      }
      // A revocation during a bounded Vault read is rechecked before any release/frame is built.
      for(String secretId:declarations.secrets()) if(!secretUse.mayUse(principal,csiId,environment,secretId)) {
        decisions.put(secretId, new Decision(DecisionOutcome.REVOKED, versions.get(secretId)));
        throw new SecretUseRevokedException(secretId);
      }
    } catch (RuntimeException e) {
      if (currentSecret != null && (entered.contains(currentSecret)
          || e instanceof SecretUseRevokedException || e instanceof ReferenceUnavailableException)) {
        DecisionOutcome outcome = e instanceof VaultProviderUnavailableException ? DecisionOutcome.VAULT_UNAVAILABLE
            : e instanceof SecretUseRevokedException ? DecisionOutcome.REVOKED : DecisionOutcome.UNAVAILABLE;
        decisions.put(currentSecret, new Decision(outcome, versions.get(currentSecret)));
      }
      var positivelyNotEntered = new java.util.LinkedHashSet<>(declarations.secrets());
      positivelyNotEntered.removeAll(entered);
      positivelyNotEntered.removeAll(decisions.keySet());
      StudioReferenceResolver.attachDecisionFacts(e, decisions, positivelyNotEntered);
      // Everything read so far is erased before the exception leaves, on every refusal path.
      variables.values().forEach(value -> Arrays.fill(value, '\0'));
      secrets.values().forEach(value -> Arrays.fill(value, '\0'));
      throw e;
    }
    return new Resolved(variables, secrets, versions, origins);
  }

  public static final class SecretTooLongException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    public SecretTooLongException(String id) {
      super("Secret exceeds the value bound: " + id);
    }
  }

  /** Names-only authorization recheck; no Vault read or list call. */
  public boolean mayUse(String principal, String csi, String environment, String secretId) {
    return secretUse.mayUse(principal, csi, environment, secretId);
  }

  /**
   * A name declared as both a variable and a secret is a refusal wherever it is found (AC-3).
   *
   * <p>At dispatch it would produce a job whose two resolved maps disagree about what the name
   * means, which is the crossed-type case the runner refuses at the envelope. Refusing it here as
   * well means the condition never depends on the far side noticing.
   */
  private static void refuseCrossedNames(ReferenceDeclarations declarations, boolean atDispatch) {
    for (String crossed : declarations.crossedNames()) {
      if (atDispatch) {
        throw new ReferenceUnavailableException(crossed);
      }
      throw new UnknownReferenceException(crossed);
    }
  }

  private static void requireName(String name) {
    if (name == null || name.isBlank()) {
      throw new UnknownReferenceException("");
    }
  }

  private static void erase(StudioVaultProvider.VaultEntry entry) {
    Arrays.fill(entry.value(), '\0');
  }

  /** Visible so a test can assert which provider a running context actually selected (AC-9). */
  public Optional<String> providerName() {
    return Optional.ofNullable(vault.name());
  }
}
      LOGGER.warn("Studio dispatch refused for execution {}: {}", executionId, e.getMessage());
      close(executionId, ExecutionErrorCode.REFERENCE_UNAVAILABLE, now);
      return false;
    }

    applyOutcome(executionId, attemptId, outcome, pendingDeadline, now);
    return true;
  }

  private boolean dispatchObserved(
      UUID id, com.fasterxml.jackson.databind.JsonNode acceptedBinding, Instant now) {
    final JsonNode binding;
    try {
      binding = transactions.execute(status -> observed.refreshRetry(acceptedBinding, instanceId));
    } catch (RuntimeException refusal) {
      close(id, observedRefusalCode(refusal), now);
      return false;
    }
    UUID attempt = UUID.fromString(binding.path("attemptId").asText());
    boolean sendCommitted = false;
    try {
      UITestRevision revision =
          revisions.findById(UUID.fromString(binding.path("revisionId").asText())).orElseThrow();
      ReferenceDeclarations declared =
          ExecutionReferences.declared(objectMapper, revision.getReferences());
      try (var resolvedJob =
          observed.job(
              binding,
              plainVariablesOf(id, declared),
              secretId -> {
                if (secretAudit == null)
                  throw new IllegalStateException("Missing secret read-entry audit");
                transactions.executeWithoutResult(
                    status -> secretAudit.replayReadEntry(binding, instanceId, secretId));
              })) {
        RunJob job = resolvedJob.runJob();
        int began = beginResolvedObservedDispatch(binding, declared.secrets(), resolvedJob);
        if (began != 1) {
          return false;
        }
        sendCommitted = true;
        DispatchOutcome outcome = runnerClient.send(job);
        applyOutcome(
            id,
            attempt,
            outcome,
            instant(statements.find(id).orElseThrow().get("pending_deadline_at")),
            now);
        return true;
      }
    } catch (VaultProviderUnavailableException failure) {
      settleObservedFailure(binding, failure, null, now);
      return false;
    } catch (StudioReferenceResolver.SecretUseRevokedException failure) {
      settleObservedFailure(binding, failure, ExecutionErrorCode.AUTHORIZATION_REVOKED, now);
      return false;
    } catch (
        com.citi.put.checks.studio.secrets.VaultStudioReferenceResolver.SecretTooLongException
            failure) {
      settleObservedFailure(binding, failure, ExecutionErrorCode.SECRET_TOO_LONG, now);
      return false;
    } catch (StudioReferenceResolver.ReferenceUnavailableException failure) {
      settleObservedFailure(binding, failure, ExecutionErrorCode.REFERENCE_UNAVAILABLE, now);
      return false;
    } catch (RuntimeException refusal) {
      if (sendCommitted) return true;
      settleObservedFailure(binding, refusal, observedRefusalCode(refusal), now);
      return false;
    }
  }

  /** Captures safe actual resolution facts before the caller erases a refused resolved job. */
  int beginResolvedObservedDispatch(
      JsonNode binding,
      List<String> declaredSecrets,
      com.citi.put.checks.studio.guided.publication.ObservedReplayAuthorization.ResolvedJob
          resolvedJob) {
    UUID id = UUID.fromString(binding.path("executionId").asText());
    UUID attempt = UUID.fromString(binding.path("attemptId").asText());
    try {
      Integer began =
          transactions.execute(
              status -> {
                observed.check(binding);
                int rows = statements.beginObservedDispatch(id, instanceId, attempt);
                if (rows == 1 && secretAudit != null)
                  secretAudit.replayRelease(
                      binding,
                      declaredSecrets,
                      resolvedJob.resolved().secretVersions(),
                      com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome
                          .RESOLVED);
                return rows;
              });
      return began == null ? 0 : began;
    } catch (RuntimeException refusal) {
      var decisions = new java.util.LinkedHashMap<String, StudioReferenceResolver.Decision>();
      resolvedJob
          .resolved()
          .secretVersions()
          .forEach(
              (secret, version) ->
                  decisions.put(
                      secret,
                      new StudioReferenceResolver.Decision(
                          StudioReferenceResolver.DecisionOutcome.RESOLVED, version)));
      StudioReferenceResolver.attachDecisionFacts(refusal, decisions, java.util.Set.of());
      throw refusal;
    }
  }

  /** Genuine pre-send decision and its owner transition commit or roll back as one unit. */
  void settleObservedFailure(
      JsonNode binding, RuntimeException failure, String failureCode, Instant now) {
    UUID id = UUID.fromString(binding.path("executionId").asText());
    UUID attempt = UUID.fromString(binding.path("attemptId").asText());
    transactions.executeWithoutResult(
        status -> {
          if (!statements.lockObservedResolutionOwner(id, instanceId, attempt)) return;
          var owner = statements.find(id).orElseThrow();
          String code =
              owner.get("cancel_requested_at") != null
                  ? ExecutionErrorCode.CANCELLED
                  : owner.get("revoked_at") != null
                      ? ExecutionErrorCode.AUTHORIZATION_REVOKED
                      : failureCode;
          auditObservedFailure(binding, failure);
          if (java.util.Arrays.stream(failure.getSuppressed())
              .anyMatch(StudioReferenceResolver.ResolutionFacts.class::isInstance)) {
            if (secretAudit == null)
              throw new IllegalStateException("Missing secret no-send audit");
            secretAudit.replayNoSendDecision(
                binding,
                instanceId,
                StudioReferenceResolver.positivelyNotEntered(failure),
                code == null
                    ? com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.NoSendDisposition
                        .REQUEUED
                    : com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.NoSendDisposition
                        .CLOSED);
          }
          int applied =
              code == null
                  ? statements.releaseObservedOutageClaim(id, instanceId, attempt)
                  : statements.closeWithError(id, code, now);
          if (applied != 1)
            throw new IllegalStateException("Observed failure decision lost its owner transition");
        });
  }

  private static String observedRefusalCode(RuntimeException refusal) {
    if (!(refusal instanceof com.citi.put.checks.studio.guided.session.GuidedSessionException))
      return ExecutionErrorCode.DISPATCH_FAILED;
    if ("CANCELLED".equals(refusal.getMessage())) return ExecutionErrorCode.CANCELLED;
    return java.util.Set.of(
                "AUTHORIZATION_EXPIRED",
                "FORBIDDEN_SCOPE",
                "SECRET_USE_REVOKED",
                "SECRET_USE_NOT_AUTHORIZED")
            .contains(refusal.getMessage())
        ? ExecutionErrorCode.AUTHORIZATION_REVOKED
        : ExecutionErrorCode.DISPATCH_FAILED;
  }

  private void auditObservedFailure(JsonNode binding, RuntimeException failure) {
    if (!org.springframework.transaction.support.TransactionSynchronizationManager
        .isActualTransactionActive())
      throw new IllegalStateException("Observed failure audit requires its owner transaction");
    if (secretAudit == null) return;
    var decisions = StudioReferenceResolver.decisionFacts(failure);
    if (decisions.isEmpty()) return;
    var declared =
        ExecutionReferences.declared(
            objectMapper,
            jdbc.queryForObject(
                "SELECT \"references\"::text FROM ui_test_revisions WHERE id=?",
                String.class,
                UUID.fromString(binding.path("revisionId").asText())));
    if (!declared.secrets().containsAll(decisions.keySet()))
