package com.citi.put.checks.scheduling.partitioning;

import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/**
 * Ensures the current month's partitions (and the lookahead) exist on <b>every</b> pod at startup.
 *
 * <p>This used to live on {@link PartitionScheduler}, which only exists where {@code
 * checks.scheduling.partition-scheduler-enabled} is true — the worker, never the API. An API pod
 * therefore started with whatever partitions a worker had last created: on a fresh database it
 * reported {@code partitions} DOWN until a worker came up, and a Studio execute it accepted in that
 * window landed in the DEFAULT partition, which then blocked the month's partition from ever being
 * created. Creation is idempotent and serialised per table ({@link
 * PartitionManager#ensurePartition}), so every pod doing it is safe.
 *
 * <p>{@link ApplicationReadyEvent} listeners run before the readiness state flips to accepting
 * traffic, so a pod is not routed requests before this has run.
 */
@Component
public class PartitionBootstrap {

  private static final Logger LOG = LoggerFactory.getLogger(PartitionBootstrap.class);

  static final int LOOKAHEAD_MONTHS = 2;
  static final List<String> MANAGED_TABLES =
      List.of(
          "execution_results",
          "ui_test_executions",
          "report_executions",
          "studio_secret_use_audit",
          "studio_observed_secret_read_entries",
          "studio_observed_no_send_decisions",
          "studio_observed_terminal_secret_settlements");

  private final JdbcTemplate jdbc;

  public PartitionBootstrap(JdbcTemplate jdbc) {
    this.jdbc = jdbc;
  }

  @EventListener(ApplicationReadyEvent.class)
  @Order(Ordered.HIGHEST_PRECEDENCE)
  public void bootstrap() {
    LOG.info(
        "Partition bootstrap — ensuring current + {} future months of partitions",
        LOOKAHEAD_MONTHS);
    ensureAll();
  }

  /** Ensures current + {@link #LOOKAHEAD_MONTHS} for every managed table. */
  public void ensureAll() {
    for (String table : MANAGED_TABLES) {
      new PartitionManager(jdbc, table).ensurePartitions(LOOKAHEAD_MONTHS);
    }
  }
}
package com.citi.put.checks.scheduling.partitioning;

import java.util.List;
import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

@Component("partitions")
public class PartitionHealthIndicator implements HealthIndicator {

  private static final int LOOKAHEAD_DAYS = 3;
  private static final List<String> MANAGED_TABLES =
      List.of(
          "execution_results",
          "ui_test_executions",
          "report_executions",
          "studio_secret_use_audit",
          "studio_observed_secret_read_entries",
          "studio_observed_no_send_decisions",
          "studio_observed_terminal_secret_settlements");

  private final JdbcTemplate jdbc;

  public PartitionHealthIndicator(JdbcTemplate jdbc) {
    this.jdbc = jdbc;
  }

  @Override
  public Health health() {
    Health.Builder builder = Health.up();
    boolean hasWarning = false;

    for (String table : MANAGED_TABLES) {
      PartitionManager manager = new PartitionManager(jdbc, table);
      PartitionManager.PartitionHealthStatus status = manager.checkHealth(LOOKAHEAD_DAYS);

      if (!status.up()) {
        return Health.down().withDetail("missing_partition", status.missingPartition()).build();
      }

      long defaultCount = countDefaultPartitionRows(table);
      if (defaultCount > 0) {
        hasWarning = true;
        builder.withDetail(
            table + "_default_rows",
            "data landed in default partition — missing monthly partition ("
                + defaultCount
                + " rows)");
      }
    }

    if (hasWarning) {
      return builder.status("WARNING").build();
    }
    return builder.build();
  }

  long countDefaultPartitionRows(String table) {
    String defaultPartition = table + "_default";
    try {
      Integer exists =
          jdbc.queryForObject(
              """
              SELECT COUNT(*) FROM pg_class c
              JOIN pg_inherits i ON c.oid = i.inhrelid
              WHERE i.inhparent = ?::regclass AND c.relname = ?
              """,
              Integer.class,
              table,
              defaultPartition);
      if (exists == null || exists == 0) {
        return 0;
      }
      Long count = jdbc.queryForObject("SELECT COUNT(*) FROM " + defaultPartition, Long.class);
      return count != null ? count : 0;
    } catch (Exception e) {
      return 0;
    }
  }
}
package com.citi.put.checks.scheduling.partitioning;

import io.micrometer.core.instrument.MeterRegistry;
import net.javacrumbs.shedlock.spring.annotation.SchedulerLock;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@ConditionalOnProperty(
    name = "checks.scheduling.partition-scheduler-enabled",
    havingValue = "true",
    matchIfMissing = true)
public class PartitionScheduler {

  private static final Logger LOG = LoggerFactory.getLogger(PartitionScheduler.class);

  private final JdbcTemplate jdbc;
  private final MeterRegistry meterRegistry;
  private final PartitionBootstrap bootstrap;

  public PartitionScheduler(
      JdbcTemplate jdbc, MeterRegistry meterRegistry, PartitionBootstrap bootstrap) {
    this.jdbc = jdbc;
    this.meterRegistry = meterRegistry;
    this.bootstrap = bootstrap;
  }

  /**
   * Daily rather than once a month (it was {@code 0 0 3 25 * ?}): creation is idempotent and cheap,
   * and a single monthly attempt meant one missed run — a worker down at 03:00 on the 25th — left
   * the next month uncreated until someone restarted a pod.
   */
  @Scheduled(cron = "0 0 3 * * ?")
  @SchedulerLock(name = "partitionCreator", lockAtMostFor = "10m", lockAtLeastFor = "30s")
  public void createFuturePartitions() {
    LOG.info(
        "Partition scheduler triggered — creating partitions for next {} months",
        PartitionBootstrap.LOOKAHEAD_MONTHS);
    bootstrap.ensureAll();
    updateMetrics();
  }

  /** Publishes the gauge at startup, after {@link PartitionBootstrap} has run. */
  @EventListener(ApplicationReadyEvent.class)
  @Order(Ordered.LOWEST_PRECEDENCE)
  public void publishMetricsAtStartup() {
    updateMetrics();
  }

  private void updateMetrics() {
    PartitionManager executionResults = new PartitionManager(jdbc, "execution_results");
    meterRegistry.gauge(
        "partition.future_months_available", executionResults.countFuturePartitions());
  }
}
package com.citi.put.checks.scheduling.partitioning;

import java.time.YearMonth;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;

public class PartitionManager {

  private static final Logger LOG = LoggerFactory.getLogger(PartitionManager.class);
  private static final DateTimeFormatter PARTITION_FMT = DateTimeFormatter.ofPattern("yyyy_MM");
  private static final DateTimeFormatter SQL_DATE_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd");

  private static final Set<String> ALLOWED_TABLES =
      Set.of(
          "execution_results",
          "ui_test_executions",
          "report_executions",
          "studio_secret_use_audit",
          "studio_observed_secret_read_entries",
          "studio_observed_no_send_decisions",
          "studio_observed_terminal_secret_settlements");

  /** The range-partition key of each managed table (V1, V7). */
  private static final Map<String, String> PARTITION_KEYS =
      Map.of(
          "execution_results", "started_at",
          "ui_test_executions", "started_at",
          "report_executions", "executed_at",
          "studio_secret_use_audit", "release_occurred_at",
          "studio_observed_secret_read_entries", "occurred_at",
          "studio_observed_no_send_decisions", "occurred_at",
          "studio_observed_terminal_secret_settlements", "occurred_at");

  private final JdbcTemplate jdbc;
  private final String parentTable;

  public PartitionManager(JdbcTemplate jdbc, String parentTable) {
    if (!ALLOWED_TABLES.contains(parentTable)) {
      throw new IllegalArgumentException("Unknown partitioned table: " + parentTable);
    }
    this.jdbc = jdbc;
    this.parentTable = parentTable;
  }

  public boolean isPartitionedTable() {
    try {
      Integer count =
          jdbc.queryForObject(
              """
              SELECT COUNT(*) FROM pg_partitioned_table pt
              JOIN pg_class c ON c.oid = pt.partrelid
              WHERE c.relname = ?
              """,
              Integer.class,
              parentTable);
      return count != null && count > 0;
    } catch (Exception e) {
      LOG.debug("Table {} does not exist or is not partitioned: {}", parentTable, e.getMessage());
      return false;
    }
  }

  /**
   * Ensures the monthly partitions for the current UTC month and the next {@code lookaheadMonths}.
   *
   * <p>Returns the names of every partition that exists for that window once the call is done,
   * whether it created them or found them.
   */
  public List<String> ensurePartitions(int lookaheadMonths) {
    if (!isPartitionedTable()) {
      LOG.debug(
          "Skipping partition creation for {} — table not partitioned or missing", parentTable);
      return List.of();
    }

    YearMonth current = YearMonth.now(ZoneOffset.UTC);
    List<String> ensured = new ArrayList<>();

    for (int i = 0; i <= lookaheadMonths; i++) {
      YearMonth month = current.plusMonths(i);
      String partitionName = partitionName(month);
      try {
        ensurePartition(month);
        ensured.add(partitionName);
      } catch (Exception e) {
        LOG.error("Failed to create partition {}: {}", partitionName, e.getMessage());
      }
    }

    return ensured;
  }

  /**
   * Creates the partition for {@code month} unless it already exists, moving any rows for that
   * month out of the DEFAULT partition into it.
   *
   * <p><b>Why the move.</b> A bare {@code CREATE TABLE … PARTITION OF … FOR VALUES …} fails while
   * the DEFAULT partition holds a row inside the new range ("updated partition constraint for
   * default partition would be violated"). Any insert that lands before the month's partition
   * exists — the dev seed (Flyway runs before any bootstrap), an API pod accepting a run before a
   * worker has bootstrapped, a missed monthly run — therefore used to make the month permanently
   * uncreatable, and the partition health indicator DOWN for good.
   *
   * <p>One {@code DO} block is one statement and so one transaction: the rows are moved aside out
   * of DEFAULT (a single {@code DELETE … RETURNING}), the partition is created and the rows are
   * re-inserted through the parent, or none of it happens. {@code CREATE … PARTITION OF} locks and
   * rescans DEFAULT, so a row for the month committed in between fails the block rather than being
   * stranded. A transaction-scoped advisory lock per parent table serialises concurrent callers
   * (every pod bootstraps), and the existence check is repeated under it.
   *
   * @return {@code true} when the partition was absent before the call and exists after it
   */
  boolean ensurePartition(YearMonth month) {
    String partitionName = partitionName(month);
    if (listPartitions().contains(partitionName)) {
      installSecretEvidenceGuards(partitionName);
      return false;
    }
    String rangeStart = month.atDay(1).format(SQL_DATE_FMT);
    String rangeEnd = month.plusMonths(1).atDay(1).format(SQL_DATE_FMT);
    String defaultPartition = parentTable + "_default";
    String partitionKey = PARTITION_KEYS.get(parentTable);
    String staging = "partition_move_" + partitionName;

    // Every interpolated value is a whitelisted table name, a name derived from it, or a date this
    // class formatted; inside the block they are quoted again with %I / %L.
    String block =
        """
        DO $partition$
        DECLARE
          cols  text;
          moved bigint := 0;
        BEGIN
          PERFORM pg_advisory_xact_lock(hashtext('checks-partition:' || '%1$s'));
          IF to_regclass('%2$s') IS NOT NULL THEN
            RETURN;
          END IF;
    return pruned;
  }

  private Set<String> listPartitions() {
    return jdbc
        .queryForList(
            """
            SELECT c.relname FROM pg_class c
            JOIN pg_inherits i ON c.oid = i.inhrelid
            WHERE i.inhparent = ?::regclass
            """,
            parentTable)
        .stream()
        .map(row -> (String) row.get("relname"))
        .collect(Collectors.toSet());
  }

  public record PartitionHealthStatus(boolean up, String missingPartition) {}
}
package com.citi.put.checks.studio.recovery;

import com.citi.put.checks.studio.StudioExecutionProperties;
import com.citi.put.checks.studio.dispatch.StudioDispatchLedgerStatements;
import com.citi.put.checks.studio.dto.ExecutionErrorCode;
import java.time.Clock;
import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

/**
 * The pending reaper (AC-29, §5.4 row 1).
 *
 * <p><b>It reclaims only rows for which no dispatch attempt was issued.</b> {@code QUEUED} or
 * {@code CLAIMED} with an expired lease is the whole of it. A {@code DISPATCHING} row is never
 * reclaimed, whatever its lease says, because an attempt was committed and sent and a browser may
 * already be running — reclaiming it would be a second dispatch, which is the one thing §5.1's
 * closing paragraph forbids. The rule is in {@link StudioDispatchLedgerStatements#findReclaimable}
 * (which does not select {@code DISPATCHING}) and again in {@link
 * StudioDispatchLedgerStatements#releaseClaim} (whose {@code WHERE} carries {@code attempt_id IS
 * NULL}), so it holds whichever way the row is reached.
 *
 * <p>Past {@code pending_deadline_at} the row is closed, and the two closures are
 * <b>distinguishable from the persisted state rather than from a log line</b>: a row that never
 * issued an attempt is {@code DISPATCH_FAILED}; a row that did, and whose send outcome was
 * therefore ambiguous, is {@code DISPATCH_UNKNOWN}. §5.1 explicitly permits that second case to end
 * as unknown rather than risk duplicate effects, and a "fix" that replays it is the failure.
 *
 * <p>Bounded in batch size, idempotent, and it runs on the worker profile only.
 */
@Component
public class PendingReaper {

  private static final Logger LOGGER = LoggerFactory.getLogger(PendingReaper.class);

  private final StudioDispatchLedgerStatements statements;
  private final FinalizationReconciler reconciler;
  private final StudioExecutionProperties properties;
  private final Clock clock;

  @Autowired
  public PendingReaper(
      StudioDispatchLedgerStatements statements,
      FinalizationReconciler reconciler,
      StudioExecutionProperties properties) {
    this(statements, reconciler, properties, Clock.systemUTC());
  }

  PendingReaper(
      StudioDispatchLedgerStatements statements,
      FinalizationReconciler reconciler,
      StudioExecutionProperties properties,
      Clock clock) {
    this.statements = statements;
    this.reconciler = reconciler;
    this.properties = properties;
    this.clock = clock;
  }

  /** One bounded pass. Returns how many rows it changed. */
  public int reapOnce() {
    Instant now = clock.instant();
    int batch = properties.dispatcherOrDefault().batchSizeOrDefault();
    int changed = 0;

    // 1. Reclaim what never issued an attempt. releaseClaim carries attempt_id IS NULL itself.
    for (UUID executionId : statements.findReclaimable(now, batch)) {
      changed += statements.releaseClaim(executionId);
    }

    // 2. Close what is past its pending deadline, distinguishing the two cases by persisted state.
    for (UUID executionId : statements.findPastPendingDeadline(now, batch)) {
      Map<String, Object> row = statements.find(executionId).orElse(null);
      if (row == null) {
        continue;
      }
      boolean attemptWasIssued = row.get("attempt_id") != null;
      if (attemptWasIssued && reconciler.reconcile(executionId)) {
        // The manifest was there: the real outcome replaced the verdict entirely.
        changed++;
        continue;
      }
      String code =
          attemptWasIssued
              ? ExecutionErrorCode.DISPATCH_UNKNOWN
              : ExecutionErrorCode.DISPATCH_FAILED;
      int closed = statements.closeByReaper(executionId, code, now);
      if (closed == 1) {
        LOGGER.info(
            "Studio execution {} closed by the pending reaper as {} past its pending deadline"
                + " (CANCELLED if a cancel was recorded)",
            executionId,
            code);
      }
      changed += closed;
    }
    return changed;
  }
}

  /** This dispatcher's lease owner, stable for the life of the bean. */
  public String instanceId() {
    return instanceId;
  }

  /**
   * One pass. Returns how many rows it dispatched.
   *
   * <p>The pass begins by relaying recorded cancels (Studio v1 WP4), whatever the kill switch says:
   * the switch stops new browser work, and a cancel only ever stops browser work that already
   * exists.
   */
  public int dispatchOnce() {
    relayCancels();
    if (!properties.enabledOrDefault()) {
      return closeUndispatchedWork();
    }
    StudioExecutionProperties.Dispatcher budget = properties.dispatcherOrDefault();
    int batchSize = budget.batchSizeOrDefault();
    Set<UUID> attempted = new HashSet<>();
    int dispatched = 0;
    // One row per claim, immediately before its own dispatch: the lease clock of each row starts
    // when that row is taken, exactly as it did when the pass claimed ids one by one. Claiming the
    // whole batch up front would start every lease at the top of the pass, and a slow send ahead
    // of a row could expire that row's lease before it was ever attempted.
    for (int taken = 0; taken < batchSize; taken++) {
      Instant now = clock.instant();
      Instant leaseExpiresAt = now.plus(budget.leaseOrDefault());
      List<UUID> claimed =
          transactions.execute(
              status -> statements.claimQueued(instanceId, leaseExpiresAt, now, 1, attempted));
      if (claimed == null || claimed.isEmpty()) {
        break;
      }
      UUID executionId = claimed.get(0);
      attempted.add(executionId);
      if (dispatchClaimed(executionId, now)) {
        dispatched++;
      }
    }
    return dispatched;
  }

  /**
   * The kill switch's second property (AC-11): queued undispatched work is closed
   * <em>explicitly</em> rather than left to a deadline. Admitted, running and finalizing rows are
   * untouched and their reports are still accepted and applied. The closure is idempotent, so a
   * second pass changes nothing and bumps no revision, and re-enabling does not resurrect a closed
   * row.
   */
  public int closeUndispatchedWork() {
    List<UUID> undispatched =
        jdbc.queryForList(
            """
